package com.infinitylibrary.builder;
import com.infinitylibrary.model.*;import com.infinitylibrary.props.*;import com.infinitylibrary.diversity.*;import java.util.*;
/** Immutable, validated template edits; never touches placed world blocks. */
public final class RoomEditor {
 public record Area(String kind,String id,Vector3i min,Vector3i size,String category,String direction,int floor,String fill,double gap,boolean rotate,boolean stack,double weight){}
 public static List<Area> areas(Room r){List<Area> out=new ArrayList<>();for(var c:r.connections()){var cells=c.cells();Vector3i min=new Vector3i(cells.stream().mapToInt(Vector3i::x).min().orElseThrow(),cells.stream().mapToInt(Vector3i::y).min().orElseThrow(),cells.stream().mapToInt(Vector3i::z).min().orElseThrow());Vector3i max=new Vector3i(cells.stream().mapToInt(Vector3i::x).max().orElseThrow(),cells.stream().mapToInt(Vector3i::y).max().orElseThrow(),cells.stream().mapToInt(Vector3i::z).max().orElseThrow());out.add(new Area("connection",c.id(),min,max.subtract(min).add(new Vector3i(1,1,1)),"",c.direction().name(),c.floor(),"EXACT",0,true,false,1));}for(var p:r.propAreas())out.add(new Area("decoration",p.id(),p.min(),p.size(),p.category(),"NORTH",0,p.fillMode().name(),p.gapPercent(),p.rotate(),p.stack(),1));for(var d:r.diversityAreas())out.add(new Area("diversity",d.id(),d.min(),d.size(),"","NORTH",0,"EXACT",0,true,false,d.originalWeight()));for(int i=0;i<r.regions().size();i++){var a=r.regions().get(i);out.add(new Area(a.kind(),"region_"+i,a.min(),a.size(),a.category(),"NORTH",0,"EXACT",0,true,false,1));}return List.copyOf(out);}
 public static void inside(Room r,Vector3i min,Vector3i size){if(min.x()<0||min.y()<0||min.z()<0||size.x()<1||size.y()<1||size.z()<1||(long)min.x()+size.x()>r.size().x()||(long)min.y()+size.y()>r.size().y()||(long)min.z()+size.z()>r.size().z())throw new IllegalArgumentException("Area must fit inside the room.");}
 public static Room area(Room r,Area a,String previous,boolean delete){
  if(!a.id().matches("[a-z0-9_-]{1,48}"))throw new IllegalArgumentException("Area ID needs lowercase letters/digits/_/- (max 48).");
  var connections=new ArrayList<>(r.connections());var props=new ArrayList<>(r.propAreas());var diversity=new ArrayList<>(r.diversityAreas());var regions=new ArrayList<>(r.regions());var existing=areas(r).stream().filter(x->(x.kind()+":"+x.id()).equals(previous)).findFirst();
  if(!previous.isEmpty()&&existing.isEmpty())throw new IllegalArgumentException("Area changed. Select it again.");if(existing.isPresent()&&!existing.get().kind().equals(a.kind()))throw new IllegalArgumentException("Area kind cannot be changed.");
  if(!delete)inside(r,a.min(),a.size());
  switch(a.kind()){
   case "connection"->{connections.removeIf(c->("connection:"+c.id()).equals(previous));if(!delete){var face=org.bukkit.block.BlockFace.valueOf(a.direction());int width,height;Vector3i anchor;var m=a.min();var s=a.size();switch(face){case NORTH,SOUTH->{if(s.z()!=1)throw new IllegalArgumentException("North/south doors need depth 1.");width=s.x();height=s.y();anchor=m.add(new Vector3i(width/2,0,0));}case EAST,WEST->{if(s.x()!=1)throw new IllegalArgumentException("East/west doors need width 1 on X.");width=s.z();height=s.y();anchor=m.add(new Vector3i(0,0,width/2));}case UP,DOWN->{if(s.y()!=1||s.x()!=s.z())throw new IllegalArgumentException("Vertical doors need a square one-block-high area.");width=s.x();height=width;anchor=m.add(new Vector3i(width/2,0,width/2));}default->throw new IllegalArgumentException("Unsupported direction");}var cp=new ConnectionPoint(a.id(),anchor,face,width,height,a.floor());if(!cp.onBoundary(r.size()))throw new IllegalArgumentException("Door must face outward on the room boundary.");if(connections.stream().anyMatch(c->c.id().equals(a.id())))throw new IllegalArgumentException("Duplicate connection ID.");connections.add(cp);}}
   case "decoration"->{props.removeIf(p->("decoration:"+p.id()).equals(previous));if(!delete)props.add(new PropArea(a.id(),a.min(),a.size(),a.category(),a.gap(),a.rotate(),a.stack(),PropArea.FillMode.valueOf(a.fill())));}
   case "diversity"->{DiversityArea old=diversity.stream().filter(d->("diversity:"+d.id()).equals(previous)).findFirst().orElse(null);diversity.removeIf(d->("diversity:"+d.id()).equals(previous));if(!delete){if(old!=null&&!old.variants().isEmpty()&&!old.size().equals(a.size()))throw new IllegalArgumentException("Captured Diversity variants require the original area size. Move the area or recapture its sources with the wand.");diversity.add(new DiversityArea(a.id(),a.min(),a.size(),a.weight(),old==null?List.of():old.variants()));}}
   case "shelf","table","seat"->{if(existing.isPresent()){int index=Integer.parseInt(existing.get().id().substring(7));regions.remove(index);if(!delete)regions.add(index,new RoomRegion(a.kind(),a.min(),a.size(),a.category()));}else if(!delete)regions.add(new RoomRegion(a.kind(),a.min(),a.size(),a.category()));}
   default->throw new IllegalArgumentException("Unsupported editable area kind.");
  }
  return copy(r,r.id(),r.type(),r.blocks(),connections,props,diversity,regions);
 }
 public static Room paint(Room r,Vector3i min,Vector3i size,String block){inside(r,min,size);long volume=(long)size.x()*size.y()*size.z();if(volume>4096)throw new IllegalArgumentException("A brush operation is limited to 4,096 blocks.");Map<Vector3i,RoomBlock> cells=new LinkedHashMap<>();for(var b:r.blocks())cells.put(b.position(),b);for(int x=min.x();x<min.x()+size.x();x++)for(int y=min.y();y<min.y()+size.y();y++)for(int z=min.z();z<min.z()+size.z();z++){var p=new Vector3i(x,y,z);cells.put(p,new RoomBlock(p,block));}return copy(r,r.id(),r.type(),List.copyOf(cells.values()),r.connections(),r.propAreas(),r.diversityAreas(),r.regions());}
 public static Room rename(Room r,String id,RoomType type){return copy(r,id,type,r.blocks(),r.connections(),r.propAreas(),r.diversityAreas(),r.regions());}
 private static Room copy(Room r,String id,RoomType type,List<RoomBlock> blocks,List<ConnectionPoint> c,List<PropArea> p,List<DiversityArea> d,List<RoomRegion> regions){return new Room(id,type,r.size(),c,blocks,r.variations(),r.spawnChance(),p,d,regions);}
 private RoomEditor(){}
}
